const e=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

export function storyOpening({headline,summary,initials,name,role,truth,outcomes}){
  return `<section class="external-story-shell"><article class="external-story-intro"><span>THE COMPLETE JOURNEY · EXTERNAL TENANT</span><h2>${headline}</h2><p>${summary}</p><div class="external-story-outcomes">${outcomes.map((item,index)=>`<div><b>0${index+1}</b><strong>${e(item[0])}</strong><small>${e(item[1])}</small></div>`).join('')}</div></article><aside class="external-story-person" data-initials="${e(initials)}"><span>MEET THE PERSON</span><h3>${e(name)}</h3><p>${e(role)}</p><strong>${e(truth)}</strong></aside></section>`;
}

export function aiPage({kicker,title,summary,buttonAttr,flow,inputs,outputs,guardrail}){
  return `<section class="external-ai-stage"><header class="external-ai-head"><div><span class="external-ai-kicker">${e(kicker)}</span><h2>${title}</h2><p>${e(summary)}</p></div><button class="primary" ${buttonAttr}>Open admin + AI stage →</button></header><div class="external-ai-flow">${flow.map((item,index)=>`<article><b>0${index+1}</b><strong>${e(item[0])}</strong><p>${e(item[1])}</p></article>`).join('')}</div><div class="external-ai-split"><section><span class="external-ai-kicker">EVIDENCE THE AGENT READS</span><h3>Ground the recommendation.</h3><ul>${inputs.map(x=>`<li>${e(x)}</li>`).join('')}</ul></section><section><span class="external-ai-kicker">WHAT THE ROOM SEES</span><h3>Make every action reviewable.</h3><ul>${outputs.map(x=>`<li>${e(x)}</li>`).join('')}</ul></section></div><div class="external-ai-guardrail"><div><span>HUMAN CONTROL</span><strong>Read → propose → approve → execute → verify → undo</strong></div><em>${e(guardrail)}</em></div></section>`;
}

export function chapterFrame({classes='',accent,glow,topline,name,role,section,title,summary,route,view,nav,context,status,content,footer}){
  return `<div class="vendor-shell external-chapter ${classes}" style="--journey-accent:${accent};--journey-glow:${glow}"><header class="vendor-topbar"><a href="#home"><img src="./assets/majorkey-logo.svg" alt="MajorKey" width="145" height="26"></a><span>${e(topline)}</span><a href="#home">All journeys</a></header><main class="external-chapter-main"><section class="external-chapter-mast"><div><div class="external-chapter-eyebrow"><b>ET</b><span>${e(name)} · ${e(role)} · ${e(section)}</span></div><h1>${title}</h1><p class="external-chapter-summary">${e(summary)}</p></div><nav class="external-chapter-nav" aria-label="${e(name)}’s journey">${nav.map(([id,num,label])=>`<a href="#${route}/${id}" ${view===id?'aria-current="page"':''}><span>${num}</span>${e(label)}</a>`).join('')}</nav></section><section class="external-chapter-context"><div>${context.map(x=>`<span>${e(x)}</span>`).join('')}</div><strong>${e(status)}</strong></section>${content}<footer class="vendor-footer"><span>Harborline · MajorKey identity workshop</span><span>${e(footer)}</span></footer></main></div>`;
}
